import{_ as d,o as a,c as r,ag as e}from"./chunks/framework.CtWPcAmt.js";const c=JSON.parse('{"title":"附录 G：常见失败排查表","description":"按「现象 → 可能原因 → 怎样修正」组织的速查表，覆盖全书最常见的失败场景。","frontmatter":{"title":"附录 G：常见失败排查表","description":"按「现象 → 可能原因 → 怎样修正」组织的速查表，覆盖全书最常见的失败场景。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"appendix/06-troubleshooting.md","filePath":"appendix/06-troubleshooting.md","lastUpdated":null}'),o={name:"appendix/06-troubleshooting.md"};function h(l,t,i,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="附录-g-常见失败排查表" tabindex="-1">附录 G：常见失败排查表 <a class="header-anchor" href="#附录-g-常见失败排查表" aria-label="Permalink to &quot;附录 G：常见失败排查表&quot;">​</a></h1><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><p>先看「现象」列找到你的问题，再读「可能原因」判断类别（输入/执行/输出/系统），最后按「怎样修正」操作。修完跑一遍第 10 章验收。</p><h2 id="一、任务描述与输入类" tabindex="-1">一、任务描述与输入类 <a class="header-anchor" href="#一、任务描述与输入类" aria-label="Permalink to &quot;一、任务描述与输入类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>Agent 方向完全不对</td><td>目标没说清（为谁做、做到什么程度）</td><td>用第 7 章任务卡六要素重写目标</td></tr><tr><td>材料没找全/用错材料</td><td>输入材料清单缺失或路径错</td><td>列清材料清单与每个的作用</td></tr><tr><td>把「材料没有」当成「事实不存在」</td><td>上下文不足</td><td>任务卡写「输入范围外视为未提供，不要推断」</td></tr><tr><td>答非所问</td><td>上下文过载/残留指令污染</td><td>新任务开新会话，只带本次相关材料（第 11 章）</td></tr><tr><td>用了过时信息</td><td>上下文污染</td><td>核对材料日期，更新 CONTEXT.md</td></tr></tbody></table><h2 id="二、执行与权限类" tabindex="-1">二、执行与权限类 <a class="header-anchor" href="#二、执行与权限类" aria-label="Permalink to &quot;二、执行与权限类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>改了/删了不该动的文件</td><td>权限开太大或没写只读</td><td>只给 output/ 写入权；先备份（第 8 章）</td></tr><tr><td>读了工作区其他文件</td><td>产品默认读取范围大</td><td>权限卡写死读取范围；验收检查读取记录</td></tr><tr><td>无弹窗但越权</td><td>权限机制 ≠ 权限行为</td><td>交付后独立检查「它碰了什么」（附录 C）</td></tr><tr><td>反复重试同一失败操作</td><td>缺信息或指令矛盾</td><td>插话补信息/澄清，别让它空转（第 9 章）</td></tr><tr><td>弹窗看不懂就点了允许</td><td>赶时间/文案不清</td><td>看不懂先拒绝，查清楚再授权</td></tr></tbody></table><h2 id="三、输出与质量类" tabindex="-1">三、输出与质量类 <a class="header-anchor" href="#三、输出与质量类" aria-label="Permalink to &quot;三、输出与质量类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>编造数据/来源</td><td>幻觉</td><td>要求标注「已验证/推断」；数字逐一核对（第 10 章）</td></tr><tr><td>6 份只交 4 份</td><td>遗漏</td><td>交付清单逐项勾；让它先报清单再开始</td></tr><tr><td>自检说全通过实际有问题</td><td>自检不可信</td><td>独立验收，不依赖自检（第 2、10 章）</td></tr><tr><td>格式/结构乱</td><td>没给输出模板</td><td>用第 12 章输出格式模板</td></tr><tr><td>结论过时（说任务没做）</td><td>状态没传递</td><td>任务卡引用 CONTEXT.md 状态（第 11 章）</td></tr></tbody></table><h2 id="四、工具与系统类" tabindex="-1">四、工具与系统类 <a class="header-anchor" href="#四、工具与系统类" aria-label="Permalink to &quot;四、工具与系统类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>换个更强模型问题依旧</td><td>问题在 Harness 不在模型</td><td>检查六层架构，先补验证/安全（第 16 章）</td></tr><tr><td>规则加了反而更差</td><td>规则与场景冲突</td><td>回滚，加适用范围再试（第 14 章）</td></tr><tr><td>多 Agent 结果互相矛盾</td><td>口径没统一/错误传导</td><td>共享上下文写口径；交接点人工检查（第 17 章）</td></tr><tr><td>改了 A 坏了 B</td><td>没做回归验证</td><td>每次修改后重跑历史任务（第 18 章）</td></tr><tr><td>版本/价格信息过期</td><td>易变信息没维护</td><td>集中到易变信息表并标核验日期（第 14、21 章）</td></tr></tbody></table><h2 id="五、账号与服务类" tabindex="-1">五、账号与服务类 <a class="header-anchor" href="#五、账号与服务类" aria-label="Permalink to &quot;五、账号与服务类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>注册/支付失败</td><td>地区或支付方式不匹配</td><td>选型前先做可用性检查（第 4、6 章）</td></tr><tr><td>账号被封</td><td>平台风控（个案）</td><td>走官方申诉；不绕过；换产品或降级使用（第 5 章 Claude）</td></tr><tr><td>客户端反复弹凭据窗口</td><td>凭据助手配置冲突</td><td>检查系统级 credential.helper 配置，统一凭据通道</td></tr></tbody></table><h2 id="六、恢复流程-通用" tabindex="-1">六、恢复流程（通用） <a class="header-anchor" href="#六、恢复流程-通用" aria-label="Permalink to &quot;六、恢复流程（通用）&quot;">​</a></h2><p>任何一次失败，按顺序做：</p><ol><li><strong>停止</strong>：不让 Agent 继续重试；</li><li><strong>备份</strong>：确认原文件完好（有 backup/ 就恢复）；</li><li><strong>分类</strong>：按上方表格判断失败类别；</li><li><strong>修正</strong>：改任务卡/约束/规则，一次只改一处；</li><li><strong>重跑</strong>：用修正后的卡重跑同类任务；</li><li><strong>沉淀</strong>：把这次教训加进你的检查清单或模板（第 18 章）。</li></ol><h2 id="何时需要人工兜底" tabindex="-1">何时需要人工兜底 <a class="header-anchor" href="#何时需要人工兜底" aria-label="Permalink to &quot;何时需要人工兜底&quot;">​</a></h2><ul><li>涉及付款、发布、删除 → 永远人工；</li><li>反复失败 2 次以上 → 先停下来诊断，不要第三次盲目重试；</li><li>输出影响医疗、法律、财务决策 → 专业人士复核；</li><li>你自己也说不清「什么算好」 → 先补验收标准，再继续。</li></ul>',18)])])}const p=d(o,[["render",h]]);export{c as __pageData,p as default};
